import{_ as a,o as s,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Raccourcis personnalisés dans la barre latérale","description":"Créer des entrées UIX dans la barre latérale de Home Assistant avec une redirection interne.","frontmatter":{"title":"Raccourcis personnalisés dans la barre latérale","description":"Créer des entrées UIX dans la barre latérale de Home Assistant avec une redirection interne."},"headers":[],"relativePath":"fr/projects/uix/using/custom-sidebar-panels.md","filePath":"fr/projects/uix/using/custom-sidebar-panels.md","lastUpdated":1793447386000}'),t={name:"fr/projects/uix/using/custom-sidebar-panels.md"};function i(o,e,l,c,d,p){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="raccourcis-personnalises-dans-la-barre-laterale" tabindex="-1">Raccourcis personnalisés dans la barre latérale <a class="header-anchor" href="#raccourcis-personnalises-dans-la-barre-laterale" aria-label="Permalink to &quot;Raccourcis personnalisés dans la barre latérale&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Disponible à partir de UIX 9.0.0-beta.6</p><p>Cette fonction appartient à l’aperçu sur <code>dev</code>, et non à la base stable 8.4.0. Comparaison effectuée le 31 octobre 2026 avec la <a href="https://github.com/Lint-Free-Technology/uix/blob/e6fb84dd715ea4bac9a330357705897ea8d44690/docs/source/using/custom-sidebar-panels.md" target="_blank" rel="noreferrer">source anglaise</a>.</p></div><p>UIX peut ajouter des entrées personnalisées à la barre latérale de Home Assistant pour accéder directement à une autre page de Home Assistant. Cela facilite l’accès aux pages souvent utilisées, normalement enfouies dans les paramètres ou dans un autre panneau.</p><p>Ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>, puis sélectionnez <strong>Manage custom sidebar panels</strong> (gérer les panneaux personnalisés de la barre latérale). Pour ajouter un panneau, choisissez son icône, saisissez son titre et sélectionnez sa destination avec le sélecteur de navigation.</p><p>Activez <strong>Admin required</strong> pour réserver l’accès au panneau aux comptes administrateurs.</p><p>Les destinations doivent être des chemins de navigation internes à la même instance Home Assistant. Ces panneaux ne redirigent pas vers des sites externes.</p><p>Chaque panneau possède une URL interne stable, gérée par UIX. Vous pouvez modifier son titre, son icône et sa destination sans le recréer. Sa suppression retire immédiatement l’entrée de la barre latérale.</p><div class="tip custom-block"><p class="custom-block-title">Ordre de la barre latérale</p><p>Chaque utilisateur peut <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">réorganiser ou masquer les entrées de la barre latérale dans son profil Home Assistant</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Fonctionnement de la redirection</p><p>Un panneau personnalisé est une redirection, pas une copie de la page cible. Lorsqu’il est sélectionné, UIX remplace son URL par la destination configurée. L’historique du navigateur ne contient donc pas d’étape de redirection supplémentaire.</p></div>',9)])])}const b=a(t,[["render",i]]);export{m as __pageData,b as default};
